create or replace function public.set_security_question(p_questions jsonb) returns boolean language plpgsql security definer set search_path = public, extensions as $$ declare v_phone text; n int; begin if jsonb_typeof(p_questions) <> 'array' then raise exception 'questions must be an array'; end if; n := jsonb_array_length(p_questions); if n < 3 then raise exception 'at least 3 security questions are required'; end if; if n > 5 then raise exception 'too many questions (max 5)'; end if; v_phone := right(coalesce((select phone from auth.users where id = auth.uid()), ''), 11); delete from public.account_security where user_id = auth.uid(); insert into public.account_security (user_id, slot, phone, question, answer_hash) select auth.uid(), ord - 1, v_phone, left(q->>'question', 100), left(q->>'answer_hash', 64) from jsonb_array_elements(p_questions) with ordinality as t(q, ord); return true; end; $$; revoke all on function public.set_security_question(jsonb) from public, anon; grant execute on function public.set_security_question(jsonb) to authenticated; 